as_number(node: Node) -> Option[float]:
    match node:
        case Node.integer(value, _):
            return Some(float(value))
        case Node.decimal(value, _, _):
            return Some(value)
        case Node.measure(value, _):
            return Some(value)
        case _:
            return None

parse_number(token: tk.Token, next_pos: int) -> Result[Step, ParseError]:
    match token.number:
        case Some(number):
            return Ok(Step(node=number_node(number, token.span), next=next_pos))
        case None:
            return Err(invalid_number(token))

number_node(number: tk.Number, span: ast.Span) -> ast.Node:
    match number:
        case tk.Number.integer(value):
            return ast.Node.integer(value, span)
        case tk.Number.decimal(value, spelling):
            return ast.Node.decimal(value, span, spelling)
        case tk.Number.measure(value):
            return ast.Node.measure(value, span)

parse_node(cursor: Cursor, depth: int) -> Result[Step, ParseError]:
    token = cursor.tokens[cursor.pos]
    next_pos = cursor.pos + 1
    match token.kind:
        case tk.Kind.lparen:
            return parse_list(cursor, next_pos, depth, token.span)
        case tk.Kind.rparen:
            return Err(located(token.span, "unexpected ')' — no matching '(' is open here"))
        case tk.Kind.atom:
            return Ok(Step(node=ast.Node.atom(token.text, token.span), next=next_pos))
        case tk.Kind.string:
            return Ok(Step(node=ast.Node.string(token.text, token.span), next=next_pos))
        case tk.Kind.int_val:
            return parse_number(token, next_pos)
        case tk.Kind.float_val:
            return parse_number(token, next_pos)
        case tk.Kind.unit_val:
            return parse_number(token, next_pos)
        case tk.Kind.si_val:
            return parse_number(token, next_pos)
        case tk.Kind.eof:
            return Err(located(token.span, "unexpected end of input — a '(' was never closed"))

parse_list(cursor: Cursor, pos: int, depth: int, open_span: ast.Span) -> Result[Step, ParseError]:
    if depth >= cursor.cap:
        return Err(located(open_span, "s-expression nesting is too deep"))
    entries: list[ast.Node] = []
    cursor_pos = pos
    while True:
        token = cursor.tokens[cursor_pos]
        # Point an unterminated list at the `(` that was never closed — the
        # actionable location, not the end of the file where scanning stopped.
        if token.kind == tk.Kind.eof:
            return Err(located(open_span, "unexpected end of input — a '(' was never closed"))
        if token.kind == tk.Kind.rparen:
            cursor_pos = cursor_pos + 1
            break
        child = parse_node(Cursor(tokens=cursor.tokens, pos=cursor_pos, cap=cursor.cap), depth + 1)?
        entries.append(child.node)
        cursor_pos = child.next
    return Ok(Step(node=ast.Node.form(entries, open_span), next=cursor_pos))

parse_dialect(src: bytes, dialect: tk.Dialect) -> Result[list[ast.Node], ParseError]:
    match tk.tokenize_dialect(src, dialect):
        case Ok(lexed):
            return parse_tokens(lexed, max_parse_depth())
        case Err(problem):
            return Err(lex_failure(problem))

parse_with_depth_cap(src: bytes, cap: int) -> Result[list[ast.Node], ParseError]:
    match tk.tokenize(src):
        case Ok(lexed):
            return parse_tokens(lexed, cap)
        case Err(problem):
            return Err(lex_failure(problem))

advance(lx: Lexer):
    if lx.pos < len(lx.src):
        if lx.src[lx.pos] == 10:
            lx.line = lx.line + 1
            lx.col = 1
        else:
            lx.col = lx.col + 1
        lx.pos = lx.pos + 1

atom_start_in(dialect: Dialect, byte: int) -> bool:
    if dialect == Dialect.kicad and byte == 59:
        return True
    return is_atom_start(byte)

atom_continue_in(dialect: Dialect, byte: int) -> bool:
    if dialect == Dialect.kicad and byte == 59:
        return True
    return is_atom_continue(byte)

longest_spelling(rows: list[ast.Suffix]) -> int:
    longest = 0
    for row in rows:
        if len(row.spelling) > longest:
            longest = len(row.spelling)
    return longest

spelled_at(lx: Lexer, window: str, spelling: str) -> bool:
    if not window.startswith(spelling):
        return False
    return not atom_continue_in(lx.dialect, peek_at(lx, len(spelling)))

suffix_at(lx: Lexer) -> Option[ast.Suffix]:
    window = lexeme(lx.src, lx.pos, lx.pos + lx.lookahead)
    for first in lx.suffixes:
        if is_scale(first.role) and window.startswith(first.spelling):
            for second in lx.suffixes:
                if second.role == ast.SuffixRole.unit:
                    pair = first.spelling + second.spelling
                    if spelled_at(lx, window, pair):
                        return Some(ast.Suffix(spelling=pair, factor=first.factor * second.factor, role=ast.SuffixRole.scale))
    for row in lx.suffixes:
        if row.role != ast.SuffixRole.unit_scale and spelled_at(lx, window, row.spelling):
            return Some(row)
    return None

number_for(kind: Kind, prefix: str, factor: float, spelling: str) -> Option[Number]:
    if kind == Kind.int_val:
        match int(prefix):
            case Some(value):
                return Some(Number.integer(value))
            case None:
                return None
    match float(prefix):
        case Some(value):
            if kind == Kind.unit_val:
                return Some(Number.measure(value * factor))
            if kind == Kind.si_val:
                return Some(Number.decimal(value * factor, Some(spelling)))
            return Some(Number.decimal(value * factor))
        case None:
            return None

read_string(lx: Lexer, line: int, col: int, offset: int) -> Result[Token, LexError]:
    advance(lx)  # skip opening "
    start = lx.pos
    closed = False
    while lx.pos < len(lx.src) and not closed:
        ch = lx.src[lx.pos]
        if ch == 92:
            advance(lx)  # skip backslash
            advance(lx)  # skip escaped char
        elif ch == 34:
            closed = True
        else:
            advance(lx)
    if not closed:
        return Err(LexError(message="unterminated string", offset=offset, line=line, col=col))
    text = lexeme(lx.src, start, lx.pos)
    advance(lx)  # skip closing "
    return Ok(Token(kind=Kind.string, text=text, span=span_at(line, col, offset)))

read_atom(lx: Lexer, line: int, col: int, offset: int) -> Token:
    start = lx.pos
    while atom_continue_in(lx.dialect, peek(lx)):
        advance(lx)
    return Token(kind=Kind.atom, text=lexeme(lx.src, start, lx.pos), span=span_at(line, col, offset))

read_operator(lx: Lexer, line: int, col: int, offset: int) -> Token:
    start = lx.pos
    advance(lx)
    if peek(lx) == 61:
        advance(lx)
    return Token(kind=Kind.atom, text=lexeme(lx.src, start, lx.pos), span=span_at(line, col, offset))

read_number(lx: Lexer, line: int, col: int, offset: int) -> Token:
    start = lx.pos
    if peek(lx) == 45:
        advance(lx)
    while is_digit(peek(lx)):
        advance(lx)
    is_float = False
    if peek(lx) == 46 and is_digit(peek_at(lx, 1)):
        is_float = True
        advance(lx)  # skip .
        while is_digit(peek(lx)):
            advance(lx)
    prefix_end = lx.pos
    prefix = lexeme(lx.src, start, prefix_end)
    span = span_at(line, col, offset)
    match suffix_at(lx):
        case Some(suffix):
            advance_by(lx, len(suffix.spelling))
            if suffix.role == ast.SuffixRole.length:
                # A dimension: its text stops before the suffix, and its value
                # is normalised to the canonical length unit.
                number = number_for(Kind.unit_val, prefix, suffix.factor, "")
                return Token(kind=Kind.unit_val, text=prefix, span=span, number=number)
            spelling = lexeme(lx.src, start, lx.pos)
            number = number_for(Kind.si_val, prefix, suffix.factor, spelling)
            return Token(kind=Kind.si_val, text=spelling, span=span, number=number)
        case None:
            if atom_continue_in(lx.dialect, peek(lx)):
                while atom_continue_in(lx.dialect, peek(lx)):
                    advance(lx)
                return Token(kind=Kind.atom, text=lexeme(lx.src, start, lx.pos), span=span)
            if is_float:
                number = number_for(Kind.float_val, prefix, 1.0, prefix)
                return Token(kind=Kind.float_val, text=prefix, span=span, number=number)
            number = number_for(Kind.int_val, prefix, 1.0, prefix)
            return Token(kind=Kind.int_val, text=prefix, span=span, number=number)

tokenize_dialect(src: bytes, dialect: Dialect) -> Result[list[Token], LexError]:
    rows = ast.suffixes()
    lx = Lexer(src=src, pos=0, line=1, col=1, suffixes=rows, lookahead=longest_spelling(rows), dialect=dialect)
    tokens: list[Token] = []
    while True:
        # Skip whitespace, and in the standard dialect `;` comments to end of
        # line. Under KiCad there is no comment syntax: a `;` is an atom byte
        # and is dispatched below like any other.
        skipping = True
        while skipping:
            byte = peek(lx)
            if is_space(byte):
                advance(lx)
            elif byte == 59 and lx.dialect == Dialect.standard:
                while peek(lx) != -1 and peek(lx) != 10:
                    advance(lx)
            else:
                skipping = False
        line = lx.line
        col = lx.col
        offset = lx.pos
        byte = peek(lx)
        if byte == -1:
            tokens.append(Token(kind=Kind.eof, text="", span=span_at(line, col, offset)))
            return Ok(tokens)
        if byte == 40:
            advance(lx)
            tokens.append(Token(kind=Kind.lparen, text="(", span=span_at(line, col, offset)))
        elif byte == 41:
            advance(lx)
            tokens.append(Token(kind=Kind.rparen, text=")", span=span_at(line, col, offset)))
        elif byte == 34:
            match read_string(lx, line, col, offset):
                case Ok(token):
                    tokens.append(token)
                case Err(problem):
                    return Err(problem)
        elif is_digit(byte) or (byte == 45 and is_digit(peek_at(lx, 1))):
            tokens.append(read_number(lx, line, col, offset))
        elif atom_start_in(lx.dialect, byte):
            tokens.append(read_atom(lx, line, col, offset))
        elif is_operator_char(byte):
            tokens.append(read_operator(lx, line, col, offset))
        else:
            return Err(LexError(message="unexpected character", offset=offset, line=line, col=col))

measured_width(text: str, fallback: int) -> int:
    if len(text) == 0:
        return fallback
    return len(text)

decimal_width(value: float) -> int:
    text = str(value)
    if text.endswith(".0"):
        return measured_width(text[0:len(text) - 2], fallback_float_width)
    return measured_width(text, fallback_float_width)

estimate_width(node: ast.Node, depth: int) -> Option[int]:
    if depth > 3:
        return None
    match node:
        case ast.Node.form(entries, _):
            total = 2
            index = 0
            while index < len(entries):
                if index > 0:
                    total = total + 1
                match estimate_width(entries[index], depth + 1):
                    case Some(width):
                        total = total + width
                    case None:
                        return None
                index = index + 1
            return Some(total)
        case ast.Node.atom(text, _):
            return Some(len(text))
        case ast.Node.string(content, _):
            return Some(len(content) + 2)
        case ast.Node.integer(value, _):
            return Some(int_width(value))
        case ast.Node.decimal(value, _, literal):
            match literal:
                case Some(text):
                    return Some(literal_width(text))
                case None:
                    return Some(decimal_width(value))
        case ast.Node.measure(value, _):
            return Some(measure_width(value))

render(nodes: list[ast.Node]) -> str:
    parts: list[str] = []
    index = 0
    while index < len(nodes):
        if index > 0:
            parts.append("\n")
        push_node(parts, nodes[index], 0)
        index = index + 1
    return "".join(parts)
